import{_ as n,C as i,o as r,c as s,a5 as a,E as o}from"./chunks/framework.BF53ZjCA.js";const f=JSON.parse('{"title":"Fancy Cuts","description":"","frontmatter":{"title":"Fancy Cuts","cutting":"fancy-cuts"},"headers":[],"relativePath":"cutting/fancy-cuts.md","filePath":"cutting/fancy-cuts.md","lastUpdated":1790876393000}'),l={name:"cutting/fancy-cuts.md"};function c(d,e,u,p,m,h){const t=i("FancyCutGrid");return r(),s("div",null,[e[0]||(e[0]=a('<h1 id="fancy-cuts" tabindex="-1">Fancy Cuts <a class="header-anchor" href="#fancy-cuts" aria-label="Permalink to &quot;Fancy Cuts&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Many non-round outlines are commonly grouped as fancy cuts, depending on the faceting pattern and trade usage. Examples include princess, emerald step, pear, oval, marquise, and heart; choice follows rough shape, inclusion placement, and taste.</p><aside class="gem-identification-boundary" aria-labelledby="identification-boundary-fancy-cuts-en"><p class="gem-identification-boundary__eyebrow">CUTTING BOUNDARY</p><h2 id="identification-boundary-fancy-cuts-en">Boundary &amp; Safety</h2><p>This page compares common trade-offs in outline and faceting style. Fancy-cut names, proportions, and market assessments vary by species and context; this page cannot guarantee appearance, price, or finished grade. </p></aside><h2 id="outline-gallery" tabindex="-1">Outline Gallery <a class="header-anchor" href="#outline-gallery" aria-label="Permalink to &quot;Outline Gallery&quot;">​</a></h2>',5)),o(t,{locale:"en"}),e[1]||(e[1]=a('<h2 id="case-flow" tabindex="-1">Case Flow <a class="header-anchor" href="#case-flow" aria-label="Permalink to &quot;Case Flow&quot;">​</a></h2><blockquote><p>Teaching case (demonstration): a market judgement cannot be derived from an outline name alone.</p></blockquote><h3 id="_1-define-the-goal" tabindex="-1">1. Define the goal <a class="header-anchor" href="#_1-define-the-goal" aria-label="Permalink to &quot;1. Define the goal&quot;">​</a></h3><p>State whether the goal is rough utilisation, outline character, corner durability, or visual performance. Different goals change tolerance for length-to-width ratio, corner treatment, and loss.</p><h3 id="_2-compare-outline-and-faceting" tabindex="-1">2. Compare outline and faceting <a class="header-anchor" href="#_2-compare-outline-and-faceting" aria-label="Permalink to &quot;2. Compare outline and faceting&quot;">​</a></h3><p>Compare pear, marquise, or emerald-step candidates against the same rough. Record length-to-width ratio, symmetry, corners, step/brilliant facet organisation, and possible bow-tie dark zones. Outline is only the entry point; it does not replace proportion or polish review.</p><h3 id="_3-review-the-visual-result" tabindex="-1">3. Review the visual result <a class="header-anchor" href="#_3-review-the-visual-result" aria-label="Permalink to &quot;3. Review the visual result&quot;">​</a></h3><p>Rotate the stone under consistent light and record uniformity, overly thin tips, and left-right balance. Keep observations from different angles separate instead of treating one view as the whole result.</p><h3 id="_4-stop-conditions" tabindex="-1">4. Stop conditions <a class="header-anchor" href="#_4-stop-conditions" aria-label="Permalink to &quot;4. Stop conditions&quot;">​</a></h3><p>If bow-tie behaviour, corner durability, or symmetry cannot be judged from the available evidence, keep multiple candidates open. Do not write “looks better” as a certain conclusion or infer price directly.</p><h2 id="core-principles" tabindex="-1">Core Principles <a class="header-anchor" href="#core-principles" aria-label="Permalink to &quot;Core Principles&quot;">​</a></h2><ul><li>Princess: square, retains round-brilliant fire; modern bridal staple.</li><li>Emerald: step facets, showcases clarity — suited to clean large stones.</li><li>Pear / marquise / heart: elongated silhouettes; need symmetric crown-pavilion to avoid bow-tie.</li><li>Cut quality, outline, proportions, symmetry, and polish jointly affect appearance and market assessment; value still varies by species and market.</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gem</th><th>Cut</th><th>Note</th></tr></thead><tbody><tr><td>diamond</td><td>Emerald step cut</td><td>Historic, elegant</td></tr><tr><td>diamond</td><td>Princess</td><td>Modern square example</td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">References &amp; Evidence Boundary</h2><p class="gem-reference-block__intro">This page supports learning and retrieval; the sources document the knowledge basis and do not make this page sufficient for identifying a specific specimen.</p><ul><li><a href="https://www.gia.edu/gia-news-research-value-factors-gem-cutting-styles-definitions" target="_blank" rel="noreferrer">GIA: Gem Cutting Styles — Definitions</a><span>Definitions of outlines, facet arrangements, step cuts, cabochons, and carving styles</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/gia-news-research/value-factors-design-cut-quality-colored-gemstone-value-factors" target="_blank" rel="noreferrer">GIA: Colored Gemstone Value Factors and Cut Quality</a><span>Cut trade-offs among proportions, symmetry, polish, rough limitations, and appearance</span><small>Open source ↗</small></li><li><a href="https://4cs.gia.edu/en-us/diamond-cut/" target="_blank" rel="noreferrer">GIA: Diamond Cut</a><span>Round-brilliant table, crown, girdle, pavilion, and the 57/58-facet count</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/emerald-quality-factor" target="_blank" rel="noreferrer">GIA: Emerald Quality Factors</a><span>How colored-stone cutting weighs color, durability, inclusions, and fractures</span><small>Open source ↗</small></li></ul></aside><aside class="gem-reference-block gem-evidence-ledger" aria-labelledby="gem-evidence-title-fancy-cuts-en"><p class="gem-reference-block__eyebrow">EVIDENCE MAP</p><h2 id="gem-evidence-title-fancy-cuts-en">Evidence map for this page</h2><p class="gem-reference-block__intro">Claims are mapped to references and labelled with their evidence status in this knowledge base.</p><ul><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--source-supported">Source-supported</strong><span>Fancy cuts commonly involve both non-round outlines and specific facet arrangements, not outline alone.</span><small>GIA: Gem Cutting Styles — Definitions</small></li><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--teaching-summary">Teaching summary</strong><span>Market assessment of fancy cuts depends on species, proportions, symmetry, polish, and demand.</span><small>GIA: Colored Gemstone Value Factors and Cut Quality</small></li><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--teaching-summary">Teaching summary</strong><span>The teaching case compares fancy cuts through outline, faceting, symmetry, and viewing conditions together.</span><small>GIA: Gem Cutting Styles — Definitions; GIA: Colored Gemstone Value Factors and Cut Quality</small></li></ul></aside><p><em>See the <a href="./intro.html">cutting overview</a>.</em></p>',17))])}const y=n(l,[["render",c]]);export{f as __pageData,y as default};
